const truthy = (v) => ['true','yes','1','y','active'].includes(String(v ?? '').trim().toLowerCase());
return $input.all()
  .filter(item => truthy(item.json.active))
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }));

const results = $input.all();
const brands = $('Attach Approved Weekly Briefs').all();
const out = [];
const now = new Date().toISOString();
const clean = value => String(value ?? '').trim();
const normalizeMedia = value => {
  const key = clean(value).toLowerCase();
  if (key.includes('image') && key.includes('video')) return 'Image + Short Video';
  if (key.includes('video')) return 'Short Video';
  return 'Image';
};
const normalizePlatform = value => {
  const key = clean(value).toLowerCase();
  if (key.includes('facebook')) return 'facebook';
  if (key.includes('instagram')) return 'instagram';
  if (key.includes('linkedin')) return 'linkedin';
  return '';
};
const parsePlatforms = value => {
  const found = clean(value).split(/[;,\n]+/).map(normalizePlatform).filter(Boolean);
  return [...new Set(found)];
};

for (let i = 0; i < results.length; i++) {
  const brand = brands[i]?.json || {};
  const raw = results[i].json.output ?? results[i].json;
  const plan = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const suppliedPlatforms = parsePlatforms(brand.weekly_platforms);
  const allowedPlatforms = suppliedPlatforms.length ? suppliedPlatforms : ['facebook', 'instagram', 'linkedin'];
  const plannedPosts = Array.isArray(plan.posts) ? plan.posts : [];
  const requestedCount = Math.max(1, Math.min(Number(brand.weekly_posts_count || 1), allowedPlatforms.length));
  const posts = plannedPosts.slice(0, requestedCount);
  const usedPlatforms = new Set();

  posts.forEach((post, index) => {
    let targetPlatform = normalizePlatform(post.target_platform);
    if (!allowedPlatforms.includes(targetPlatform) || usedPlatforms.has(targetPlatform)) {
      targetPlatform = allowedPlatforms.find(platform => !usedPlatforms.has(platform)) || '';
    }
    if (!targetPlatform) return;
    usedPlatforms.add(targetPlatform);

    const id = [brand.brand_id || 'brand', now.slice(0,10), Date.now(), index + 1, Math.random().toString(36).slice(2,7)].join('-');
    const media = normalizeMedia(post.media_type || brand.weekly_media_type);
    const needsImage = media.includes('Image');
    const needsVideo = media.includes('Video');
    out.push({ json: {
      id, brand_id: brand.brand_id, campaign: post.campaign || brand.weekly_campaign || '',
      target_platform: targetPlatform,
      content_pillar: post.content_pillar, topic_idea: post.topic_idea,
      target_audience: brand.target_audience || '', tone_of_voice: brand.tone_of_voice || '',
      scheduled_at: post.scheduled_at, status: 'Needs Draft',
      generated_linkedin: '', generated_facebook: '', generated_instagram: '', image_url: '', image_brief: '', link_url: '',
      image_status: needsImage ? 'Pending' : 'Not Requested', image_file_id: '', image_attempts: 0,
      media_type: media, video_brief: '', video_script: '',
      video_status: needsVideo ? 'Pending' : 'Not Requested', video_url: '', video_file_id: '', video_attempts: 0,
      video_provider: '', video_style: clean(post.video_style || brand.weekly_video_style),
      video_duration_seconds: Math.max(3, Math.min(10, Number(post.video_duration_seconds || brand.weekly_video_duration_seconds || 8))),
      audit_id: '', audit_status: 'Not Submitted', audit_submitted_at: '', audit_version: 1,
      video_aspect_ratio: clean(post.video_aspect_ratio || brand.weekly_video_aspect_ratio) || '9:16',
      publish_facebook: brand.publish_facebook, publish_instagram: brand.publish_instagram, publish_linkedin: brand.publish_linkedin,
      facebook_status: 'Pending', facebook_post_id: '', facebook_attempts: 0,
      instagram_status: 'Pending', instagram_post_id: '', instagram_attempts: 0,
      linkedin_status: 'Pending', linkedin_post_id: '', linkedin_attempts: 0,
      last_error: '', next_retry_at: '', approved_by: '', approved_at: '', published_at: '', updated_at: now
    } });
  });
}
return out;

const rows = $input.all().map(item => item.json);
const brands = $('Read Brand Configuration').all().map(item => item.json);
const serviceDetails = $('Read Service Details').all().map(item => item.json || {});
const serviceFactsFor = (brandId, pillar, topic) => {
  const b = key(brandId); const p = key(pillar); const t = key(topic);
  const row = serviceDetails.find(r => key(r.brand_id) === b && key(r.service_value) &&
    (key(r.service_value) === p || p.includes(key(r.service_value)) || t.includes(key(r.service_value))));
  if (!row) return '';
  return [
    clean(row.summary) && ('Summary: ' + clean(row.summary)),
    clean(row.scenarios) && ('Typical scenarios: ' + clean(row.scenarios)),
    clean(row.differentiators) && ('Differentiators: ' + clean(row.differentiators)),
    clean(row.keywords) && ('Keywords: ' + clean(row.keywords)),
    clean(row.avoid) && ('Must avoid: ' + clean(row.avoid)),
  ].filter(Boolean).join('\n');
};
const config = $('Runtime Configuration').first().json;
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

const clean = (v) => String(v ?? '').trim();
const key = (v) => clean(v).toLowerCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ');
const bool = (v) => ['true','yes','1','y','on','enabled'].includes(key(v));
const num = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
const has = (v) => clean(v) !== '';

function enabled(row, brand, platform) {
  const target = key(row.target_platform);
  if (target && target !== platform) return false;
  const own = row['publish_' + platform];
  return has(own) ? bool(own) : bool(brand['publish_' + platform]);
}
function statusOf(row, platform) {
  return key(row[platform + '_status']);
}
function attemptsOf(row, platform) {
  return num(row[platform + '_attempts']);
}

const out = [];

// v10.7: Gemini rejects video generations that arrive back to back - the engine used to
// hand it every eligible row at once and collect 429s ("Try spacing your requests out").
// A rejected call costs nothing, but the row lands as Failed and needs a retry, so the
// queue crawls. Only VIDEO_PER_RUN videos are started per run now; the rest keep their
// state and are picked up by the next run, which is exactly what the console's Run
// button already tells the operator to do.
const VIDEO_PER_RUN = Number(config.video_per_run || 1);
let videosStarted = 0;

for (let index = 0; index < rows.length; index++) {
  const row = rows[index];
  // v9.5.1: Google Sheets returns trailing/blank rows. They have no id, so every downstream
  // update fails with "The 'Column to Match On' parameter is required". Skip them silently -
  // a blank spreadsheet row is not a work item and must not be flagged as Needs Review.
  if (!has(row.id)) continue;
  const brand = brands.find(b => clean(b.brand_id) === clean(row.brand_id));
  let action = '';
  let finalStatus = '';
  let validationError = '';

  if (!brand) {
    action = 'fix';
    validationError = 'No matching brand_id was found in the Brands sheet.';
  }
  const brandInactive = Boolean(brand && has(brand.active) && !bool(brand.active));

  const facebook = brand ? enabled(row, brand, 'facebook') : false;
  const instagram = brand ? enabled(row, brand, 'instagram') : false;
  const linkedin = brand ? enabled(row, brand, 'linkedin') : false;
  const required = [
    facebook ? 'facebook' : null,
    instagram ? 'instagram' : null,
    linkedin ? 'linkedin' : null
  ].filter(Boolean);

  const state = key(row.status);
  const scheduledMs = has(row.scheduled_at) ? Date.parse(row.scheduled_at) : nowMs;
  const scheduledValid = Number.isFinite(scheduledMs);
  const isDue = scheduledValid && scheduledMs <= nowMs;
  const retryMs = has(row.next_retry_at) ? Date.parse(row.next_retry_at) : 0;
  const retryDue = !Number.isFinite(retryMs) || retryMs <= nowMs;
  const maxAttempts = Number(config.max_attempts || 3);
  const imageAttempts = num(row.image_attempts);
  const imageState = key(row.image_status);
  const mediaType = clean(row.media_type) || 'Image';
  const needsVideo = mediaType.toLowerCase().includes('video');
  const selectedVideoProvider = key(row.video_provider || config.video_provider || 'Google Gemini');
  // An image is generated only when the selected media package explicitly includes Image.
  const needsImage = mediaType.toLowerCase().includes('image');
  const videoState = key(row.video_status);
  const videoAttempts = num(row.video_attempts);
  const mediaReady = (!needsImage || has(row.image_url)) && (!needsVideo || (videoState === 'ready' && has(row.video_url)));
  const auditMissing = !has(row.audit_id);
  const allPublished = required.length > 0 && required.every(p => statusOf(row,p) === 'published');
  const retryable = required.some(p => statusOf(row,p) !== 'published' && attemptsOf(row,p) < maxAttempts);
  const exhausted = required.length > 0 && required.every(p => statusOf(row,p) === 'published' || attemptsOf(row,p) >= maxAttempts);

  if (!action && state === 'cancelled') {
    continue;
  }

  if (!action && ['needs draft','draft requested'].includes(state)) {
    action = 'draft';
  } else if (!action && state === 'awaiting approval' && needsImage && !has(row.image_url)) {
    // FIX (added by diagnosis session): a row could get stuck at image_status='Generating'
    // forever if the image step crashed/timed out without writing a final status - this
    // branch used to skip such rows unconditionally with no way out. Now: after being stuck
    // in 'Generating' longer than generatingStaleMs, treat it like any other retry-eligible row.
    // v9.6.0: 10 minutes, not 20. Image generation takes about a minute, so a row still
    // marked Generating after 10 minutes is stuck, not slow. Halving the window halves the
    // worst-case time a crashed image step blocks a row with nobody touching the sheet.
    const generatingStaleMs = 10 * 60000;
    const generatingSinceMs = has(row.updated_at) ? Date.parse(row.updated_at) : NaN;
    const isStaleGenerating = imageState === 'generating' && Number.isFinite(generatingSinceMs) && (nowMs - generatingSinceMs) > generatingStaleMs;
    if (!isStaleGenerating && (imageState === 'generating' || !retryDue)) {
      continue;
    } else if (imageAttempts >= maxAttempts) {
      action = 'fix';
      validationError = isStaleGenerating
        ? 'Image generation was stuck in Generating for over 10 minutes and never completed (checked ' + maxAttempts + ' time(s)). Check the Generate Content Image / OpenAI credential.'
        : 'Maximum image generation attempts reached.';
    } else {
      action = 'image';
    }
  } else if (!action && state === 'awaiting approval' && needsVideo && (videoState !== 'ready' || !has(row.video_url))) {
    const generatingStaleMs = 30 * 60000;
    const generatingSinceMs = has(row.updated_at) ? Date.parse(row.updated_at) : NaN;
    const isStaleGenerating = videoState === 'generating' && Number.isFinite(generatingSinceMs) && (nowMs - generatingSinceMs) > generatingStaleMs;
    if (!isStaleGenerating && (videoState === 'generating' || !retryDue)) {
      continue;
    } else if (videoAttempts >= maxAttempts) {
      action = 'fix';
      validationError = isStaleGenerating
        ? 'Video generation was stuck in Generating for over 30 minutes and reached the retry limit.'
        : 'Maximum video generation attempts reached.';
    } else if (videosStarted >= VIDEO_PER_RUN) {
      // already starting as many videos as one run may safely start - leave this row
      // untouched so the next run finds it in exactly the same state.
      continue;
    } else {
      action = 'video';
      videosStarted++;
    }
  } else if (!action && state === 'awaiting approval' && mediaReady && auditMissing) {
    action = 'audit';
  } else if (!action && ['awaiting approval','under audit','needs review','published'].includes(state)) {
    continue;
  } else if (!action && state === 'approved' && needsVideo && (videoState !== 'ready' || !has(row.video_url))) {
    action = 'fix';
    validationError = 'Video content is approved but the final video file is not Ready.';
  } else if (!action && !scheduledValid) {
    action = 'fix';
    validationError = 'scheduled_at is not a valid ISO 8601 date/time.';
  } else if (!action && required.length === 0) {
    action = 'fix';
    validationError = 'No publishing platform is enabled for this post or brand.';
  } else if (!action && instagram && needsImage && !has(row.image_url)) {
    action = 'fix';
    validationError = 'Instagram image publishing is enabled but image_url is empty.';
  } else if (!action && instagram && needsVideo && !has(row.video_url)) {
    action = 'fix';
    validationError = 'Instagram Reel publishing is enabled but video_url is empty.';
  } else if (!action && instagram && needsImage && /drive\.google\.com/i.test(clean(row.image_url))) {
    action = 'fix';
    validationError = 'Instagram requires a public direct image URL. The Google Drive link is for review only.';
  } else if (!action && facebook && !has(brand.facebook_page_id)) {
    action = 'fix';
    validationError = 'Facebook is enabled but facebook_page_id is missing in Brands.';
  } else if (!action && instagram && !has(brand.instagram_user_id)) {
    action = 'fix';
    validationError = 'Instagram is enabled but instagram_user_id is missing in Brands.';
  } else if (!action && linkedin && !has(brand.linkedin_organization_id)) {
    action = 'fix';
    validationError = 'LinkedIn is enabled but linkedin_organization_id is missing in Brands.';
  } else if (!action && brandInactive && ['approved','publishing','partially published','failed'].includes(state)) {
    action = 'fix';
    validationError = 'Brand is inactive or its social accounts are not connected.';
  } else if (!action && state === 'approved' && isDue) {
    action = allPublished ? 'finalize' : 'publish';
    finalStatus = allPublished ? 'Published' : '';
  } else if (!action && ['publishing','partially published','failed'].includes(state)) {
    if (allPublished) {
      action = 'finalize';
      finalStatus = 'Published';
    } else if (exhausted && !retryable) {
      action = 'finalize';
      finalStatus = 'Failed';
      validationError = 'Maximum publishing attempts reached for one or more platforms.';
    } else if (retryDue) {
      action = 'publish';
    }
  }

  if (!action) continue;

  const linkedinValue = clean(brand?.linkedin_organization_id);
  out.push({
    json: {
      ...row,
      service_facts: serviceFactsFor(row.brand_id, row.content_pillar, row.topic_idea),
      company_name: brand?.company_name || '',
      brand_context: brand?.brand_context || '',
      logo_url: brand?.logo_url || '',
      brand_primary_color: brand?.brand_primary_color || '',
      brand_secondary_color: brand?.brand_secondary_color || '',
      image_branding_instructions: brand?.image_branding_instructions || '',
      brand_target_audience: brand?.target_audience || '',
      brand_tone_of_voice: brand?.tone_of_voice || '',
      default_cta: brand?.default_cta || '',
      facebook_page_id: clean(brand?.facebook_page_id),
      instagram_user_id: clean(brand?.instagram_user_id),
      linkedin_organization_id: linkedinValue,
      linkedin_author: linkedinValue.startsWith('urn:') ? linkedinValue : (linkedinValue ? 'urn:li:organization:' + linkedinValue : ''),
      _publish_facebook: facebook,
      _publish_instagram: instagram,
      _publish_linkedin: linkedin,
      _action: action,
      _final_status: finalStatus,
      _validation_error: validationError,
      _max_attempts: maxAttempts,
      _retry_minutes: Number(config.retry_minutes || 10),
      _classified_at: nowIso
    },
    pairedItem: { item: index }
  });
}
// Keep expensive media generation sequential. At most one image or video request is released per worker run.
const nonMediaJobs = out.filter(item => !['image','video'].includes(item.json._action));
const mediaJobs = out.filter(item => ['image','video'].includes(item.json._action));
return [...nonMediaJobs, ...mediaJobs.slice(0, 1)];

const source = $('Validate and Classify Queue Rows').item.json;
let output = $json.output ?? $json;
if (typeof output === 'string') output = JSON.parse(output);
const media = String(source.media_type || 'Image');
const mediaKey = media.toLowerCase();
const needsVideo = mediaKey.includes('video');
const selectedVideoProvider = String(source.video_provider || $('Runtime Configuration').first().json.video_provider || 'Google Gemini').trim();
const needsImage = mediaKey.includes('image') || (needsVideo && selectedVideoProvider.toLowerCase().includes('creatomate'));
const currentVideoStatus = String(source.video_status || '').trim();
const target = String(source.target_platform || '').trim().toLowerCase();
const generatedLinkedin = target === 'linkedin' ? String(output.linkedin || '').trim() : '';
const generatedFacebook = target === 'facebook' ? String(output.facebook || '').trim() : '';
const generatedInstagram = target === 'instagram' ? String(output.instagram || '').trim() : '';
if (!generatedLinkedin && !generatedFacebook && !generatedInstagram) {
  throw new Error('The model did not return copy for target_platform=' + target);
}
return { json: {
  id: source.id,
  target_platform: target,
  generated_linkedin: generatedLinkedin,
  generated_facebook: generatedFacebook,
  generated_instagram: generatedInstagram,
  image_brief: output.image_brief || '', image_status: needsImage ? (source.image_status || 'Pending') : 'Not Requested',
  image_file_id: source.image_file_id || '', image_attempts: Number(source.image_attempts || 0),
  media_type: media, video_brief: output.video_brief || source.video_brief || '', video_script: output.video_script || source.video_script || '',
  video_status: needsVideo ? (currentVideoStatus === 'Ready' ? 'Ready' : 'Pending') : 'Not Requested',
  video_attempts: Number(source.video_attempts || 0), video_provider: needsVideo ? selectedVideoProvider : '',
  video_style: source.video_style || '', video_duration_seconds: Math.max(3, Math.min(10, Number(source.video_duration_seconds || $('Runtime Configuration').first().json.video_duration_seconds || 8))),
  video_aspect_ratio: source.video_aspect_ratio || (target === 'instagram' ? '9:16' : '16:9'),
  audit_id: '', audit_status: 'Not Submitted', audit_submitted_at: '', audit_version: Math.max(1, Number(source.audit_version || 1)),
  status: 'Awaiting Approval', last_error: '', next_retry_at: '', updated_at: new Date().toISOString()
} };

const draft = $json;
const queueRow = $('Validate and Classify Queue Rows').item.json;
const clean = value => String(value ?? '').trim();
const key = value => clean(value).toLowerCase();

const brands = $('Read Brand Configuration').all().map(item => item.json);
const brand = brands.find(item => clean(item.brand_id) === clean(queueRow.brand_id)) || {};
const source = { ...brand, ...queueRow, ...draft };
const intent = [source.campaign, source.content_pillar, source.topic_idea].map(key).join(' ');
const isOccasion = /social occasion|holiday|eid|ramadan|christmas|easter|new year|thanksgiving|labor day|independence day|good friday|palm sunday|mawlid|women.?s day/.test(intent);
const isRecruitment = /recruitment|hiring|career|job vacancy|job posting/.test(intent);
const shouldAppendServiceContacts = !isOccasion && !isRecruitment;

const contacts = [
  ['📞 Phone', clean(source.contact_phone)],
  ['✉️ Email', clean(source.contact_email)],
  ['🌐 Website', clean(source.website_url)],
  ['📘 Facebook', clean(source.facebook_url)],
  ['📸 Instagram', clean(source.instagram_url)],
  ['💼 LinkedIn', clean(source.linkedin_url)],
  ['💬 Messenger', clean(source.messenger_url)],
  ['🟢 WhatsApp', clean(source.whatsapp_url)],
  ['⭐ Yelp', clean(source.yelp_url)],
].filter(([, value]) => value);

const verifiedValues = contacts.map(([, value]) => value);
const fallback = shouldAppendServiceContacts ? clean(source.default_cta) : '';
const contactBlock = shouldAppendServiceContacts
  ? (contacts.length
      ? [
          '📲 CONTACT & REQUEST SERVICE',
          ...contacts.map(([label, value]) => label + ': ' + value),
        ].join('\n')
      : fallback)
  : '';

function removeOldContactDetails(value) {
  const body = clean(value);
  if (!body) return '';
  return body
    .split(/\r?\n/)
    .filter(line => {
      const currentLine = clean(line);
      if (!currentLine) return true;
      if (verifiedValues.some(value => value && currentLine.includes(value))) return false;
      if (/^(?:📞|📲)?\s*(?:REQUEST SERVICE|CONTACT|CONTACT US|CONTACT & REQUEST SERVICE)\s*:?\s*$/i.test(currentLine)) return false;
      return true;
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function finalizeCopy(value) {
  const body = removeOldContactDetails(value);
  if (!contactBlock) return body;
  if (!body) return contactBlock;
  return body + '\n\n' + contactBlock;
}

return {
  json: {
    ...draft,
    generated_facebook: finalizeCopy(draft.generated_facebook),
    generated_instagram: finalizeCopy(draft.generated_instagram),
    generated_linkedin: finalizeCopy(draft.generated_linkedin),
    contact_block: contactBlock,
    contacts_verified: contacts.length > 0,
    contact_block_applied: Boolean(contactBlock),
    content_intent: isOccasion ? 'occasion' : isRecruitment ? 'recruitment' : 'service',
  },
};

return { json: {
  ...$json,
  status: 'Publishing',
  last_error: '',
  updated_at: new Date().toISOString()
} };

const rows = $input.all().map(item => item.json);
const brands = $('Read Brand Configuration').all().map(item => item.json);
const config = $('Runtime Configuration').first().json;
const clean = v => String(v ?? '').trim();
const key = v => clean(v).toLowerCase();
const bool = v => ['true','yes','1','y','on','enabled'].includes(key(v));
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
const has = v => clean(v) !== '';
const out = [];

for (let i = 0; i < rows.length; i++) {
  const row = rows[i];
  const brand = brands.find(b => clean(b.brand_id) === clean(row.brand_id)) || {};
  const isEnabled = platform => has(row['publish_' + platform])
    ? bool(row['publish_' + platform])
    : bool(brand['publish_' + platform]);

  const jobs = [
    ['facebook', row.generated_facebook, brand.facebook_page_id],
    ['instagram', row.generated_instagram, brand.instagram_user_id],
    ['linkedin', row.generated_linkedin, brand.linkedin_organization_id]
  ];

  for (const [platform, copy, accountId] of jobs) {
    const targetPlatform = key(row.target_platform);
    if (targetPlatform && targetPlatform !== platform) continue;
    if (!isEnabled(platform)) continue;
    if (key(row[platform + '_status']) === 'published') continue;
    const attempts = num(row[platform + '_attempts']);
    if (attempts >= Number(config.max_attempts || 3)) continue;

    const linkedinValue = clean(brand.linkedin_organization_id);
    out.push({
      json: {
        ...row,
        company_name: brand.company_name || '',
        platform,
        copy: copy || '',
        has_image: has(row.image_url) && key(row.media_type).includes('image'),
        has_video: has(row.video_url) && key(row.media_type).includes('video'),
        image_url: clean(row.image_url),
        video_url: clean(row.video_url),
        account_id: clean(accountId),
        facebook_page_id: clean(brand.facebook_page_id),
        instagram_user_id: clean(brand.instagram_user_id),
        linkedin_organization_id: linkedinValue,
        linkedin_author: linkedinValue.startsWith('urn:') ? linkedinValue : (linkedinValue ? 'urn:li:organization:' + linkedinValue : ''),
        _attempt: attempts + 1,
        _retry_minutes: Number(config.retry_minutes || 10)
      },
      pairedItem: { item: i }
    });
  }
}
return out;

const src = $('Build Platform Jobs').item.json;
const response = $json;
const code = Number(response.statusCode || 0);
const body = response.body ?? response;
const ok = code >= 200 && code < 300 && !!body.id;
const error = ok ? '' : String(body?.error?.message || response?.error?.message || response?.message || 'Facebook publishing failed.');
const now = new Date();
return { json: {
  id: src.id,
  facebook_status: ok ? 'Published' : 'Failed',
  facebook_post_id: ok ? String(body.id) : '',
  facebook_attempts: src._attempt,
  status: 'Partially Published',
  last_error: error,
  next_retry_at: ok ? '' : new Date(now.getTime() + src._retry_minutes * 60000).toISOString(),
  updated_at: now.toISOString(),
  log_id: src.id + '-facebook-' + Date.now(),
  post_id: src.id,
  brand_id: src.brand_id,
  company_name: src.company_name,
  platform: 'facebook',
  platform_status: ok ? 'Published' : 'Failed',
  platform_post_id: ok ? String(body.id) : '',
  attempt: src._attempt,
  error_message: error,
  platform_published_at: ok ? now.toISOString() : '',
  logged_at: now.toISOString()
} };

parameters.jsonBody:
={{ JSON.stringify({
  author: $json.linkedin_author,
  commentary: $json.copy,
