}).sort((a, b) => clean(b.updated_at || b.approved_at).localeCompare(clean(a.updated_at || a.approved_at)));
const byBrand = new Map();
for (const row of selected) if (!byBrand.has(lower(row.brand_id))) byBrand.set(lower(row.brand_id), row);
