const lower = value => clean(value).toLowerCase();
const truthy = value => ['true','yes','1','y','active','enabled'].includes(lower(value));
const normalizeMedia = value => {
  const key = lower(value);
  if (key.includes('image') && key.includes('video')) return 'Image + Short Video';
  if (key.includes('video')) return 'Short Video';
  return 'Image';
};
const now = new Date().toISOString();
const out = [];
for (const job of jobs) {
