    'Application phone: ' + clean(job.application_phone), 'Extra instructions: ' + clean(job.extra_instructions),
    'Do not invent any missing fact, compensation, qualification, location, contact detail, or benefit.'
  ].join('\n');
  out.push({ json: {
    id: 'job-' + clean(job.job_id) + '-' + Date.now().toString(36), brand_id: clean(job.brand_id),
    campaign: 'Hiring - ' + clean(job.job_title), content_pillar: 'Recruitment - ' + clean(job.job_title),
    topic_idea: details, target_audience: 'Qualified candidates for ' + clean(job.job_title) + (clean(job.location) ? ' in ' + clean(job.location) : ''),
    tone_of_voice: clean(brand.tone_of_voice) || 'Professional, clear, inclusive, and factual.',
