    generated_linkedin: '', generated_facebook: '', generated_instagram: '', image_url: '',
    image_brief: clean(job.image_style) || 'Photorealistic recruitment image showing a professional relevant to the exact role in a credible workplace, without text or logos.',
    link_url: clean(job.application_url), media_type: media,
    video_brief: clean(job.video_brief), video_script: '', video_status: needsVideo ? 'Pending' : 'Not Requested',
    video_url: '', video_file_id: '', video_attempts: 0, video_provider: '', video_style: clean(job.video_style),
    video_duration_seconds: Math.max(3, Math.min(10, Number(job.video_duration_seconds || 8))),
    video_aspect_ratio: clean(job.video_aspect_ratio) || '9:16',
    publish_facebook: wants('facebook') && truthy(brand.publish_facebook),
    publish_instagram: wants('instagram') && truthy(brand.publish_instagram),
    publish_linkedin: wants('linkedin') && truthy(brand.publish_linkedin),
    facebook_status: 'Pending', facebook_post_id: '', facebook_attempts: 0,
