  const contacts = [
    ['📞 Phone', clean(source.contact_phone)],
    ['✉️ Email', clean(source.contact_email)],
    ['🌐 Website', clean(source.website_url)],
    ['📘 Facebook', clean(source.facebook_url)],
    ['📸 Instagram', clean(source.instagram_url)],
    ['💼 LinkedIn', clean(source.linkedin_url)],
    ['💬 Messenger', clean(source.messenger_url)],
    ['🟢 WhatsApp', clean(source.whatsapp_url)],
    ['⭐ Yelp', clean(source.yelp_url)],
  ].filter(([, value]) => value);

  if (!contacts.length) return clean(source.default_cta);
  return [
    '📲 CONTACT & REQUEST SERVICE',
    ...contacts.map(([label, value]) => label + ': ' + value),
  ].join('\n');
}

function ensureContactBlock(value, contactBlock) {
  const body = clean(value);
  if (!contactBlock || body.includes('📲 CONTACT & REQUEST SERVICE')) return body;
  return body ? body + '\n\n' + contactBlock : contactBlock;
}

return inputs.flatMap((sourceItem, sourceIndex) => {
  const pairedIndex = Number.isInteger(sourceItem.pairedItem?.item)
    ? sourceItem.pairedItem.item
    : sourceIndex;
  const originalPost = lockedPosts[pairedIndex]?.json || lockedPosts[sourceIndex]?.json || {};
  const source = { ...originalPost, ...sourceItem.json };
  const brand = brands.find(item => clean(item.brand_id) === clean(source.brand_id)) || {};
  const fullSource = { ...brand, ...source };
  const company = clean(fullSource.company_name) || clean(fullSource.brand_id) || 'Madama Group Brand';
  const topic = clean(fullSource.content_pillar) || clean(fullSource.campaign) || 'Social media content';
  const targetPlatform = clean(fullSource.target_platform).toUpperCase();
  const contentId = clean(fullSource.id);
  const intent = [fullSource.campaign, fullSource.content_pillar, fullSource.topic_idea].map(clean).join(' ').toLowerCase();
  const isOccasion = /social occasion|holiday|eid|ramadan|christmas|easter|new year|thanksgiving|labor day|independence day|good friday|palm sunday|mawlid|women.?s day/.test(intent);
  const isRecruitment = /recruitment|hiring|career|job vacancy|job posting/.test(intent);
  const contactBlock = (isOccasion || isRecruitment) ? '' : buildContactBlock(fullSource);
  const entries = [
    ['FACEBOOK', fullSource.generated_facebook],
    ['INSTAGRAM', fullSource.generated_instagram],
    ['LINKEDIN', fullSource.generated_linkedin],
  ].filter(([platform, value]) => clean(value) && (!targetPlatform || platform === targetPlatform));

  return entries.map(([platform, value]) => ({
    json: {
      ...fullSource,
      telegram_chat_id: chatId,
      telegram_platform: platform,
      telegram_copy: ensureContactBlock(value, contactBlock),
      telegram_caption: ('🖼️ ' + platform + ' — ' + company + '\n🧾 ' + contentId + '\n\n' + ensureContactBlock(value, contactBlock)).slice(0, 1024),
    },
    binary: sourceItem.binary,
    pairedItem: { item: sourceIndex },
  }));
});

const photoResponse = $json;
const preview = $('Prepare Telegram Preview').item.json;
const clean = value => String(value ?? '').trim();

// v9.5.6 FIX: this node runs in 'Run Once for Each Item' mode, where the code MUST return a
// single object with a 'json' property. The old `return []` therefore crashed with
// "A 'json' property isn't an object" every time the copy already fitted in the image caption
// - which is the common case, not an edge case.
// It was also wrong in a second way: this node sits INSIDE 'Loop Telegram Platform Previews',
// and the loop is fed back by 'Telegram - Send Platform Copy'. Emitting zero items would have
// stopped that feedback and silently ended the loop, so the remaining platform previews would
// never be sent. So instead of dropping the item we always emit one and let the new IF node
// 'Separate Copy Needed?' decide whether to actually send it - both of its branches return to
// the loop, so every platform is processed.
const __fullCopy = clean(preview.telegram_copy);
const company = clean(preview.company_name) || clean(preview.brand_id) || 'Madama Group Brand';
const platform = clean(preview.telegram_platform) || 'SOCIAL';
const contentId = clean(preview.id);
const messageId = photoResponse.result?.message_id || photoResponse.message_id || '';

if (__fullCopy.length <= 900) {
  return { json: {
    telegram_copy_needed: false,
    telegram_chat_id: preview.telegram_chat_id,
    telegram_message: '',
    telegram_platform: platform,
    content_id: contentId,
    reply_to_message_id: messageId,
  } };
}

function fitBody(value, maxLength) {
  const full = clean(value);
  if (full.length <= maxLength) return full;

  let markerIndex = full.lastIndexOf('\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n\ud83d\udcf2 CONTACT & REQUEST SERVICE');
  if (markerIndex < 0) markerIndex = full.lastIndexOf('\ud83d\udcf2 CONTACT & REQUEST SERVICE');

  if (markerIndex >= 0) {
    const contactBlock = full.slice(markerIndex).trim();
    const availableMain = Math.max(0, maxLength - contactBlock.length - 7);
    const main = full.slice(0, markerIndex).trim().slice(0, availableMain).trim();
    return main + '\n...\n\n' + contactBlock;
  }

  return full.slice(0, Math.max(0, maxLength - 3)).trim() + '...';
}

const header = '\ud83d\udce3 ' + platform + ' COPY\n\ud83c\udfe2 ' + company + '\n\ud83e\uddfe ' + contentId + '\n\n';
const footer = '\n\n\ud83d\udd0e REVIEW COPY \u2014 Telegram does not publish this content';
const maxBody = Math.max(0, 3900 - header.length - footer.length);

return { json: {
  telegram_copy_needed: true,
  telegram_chat_id: preview.telegram_chat_id,
  telegram_message: header + fitBody(preview.telegram_copy, maxBody) + footer,
  telegram_platform: platform,
  content_id: contentId,
  reply_to_message_id: messageId,
} };

