const source = $('Convert Image to Binary').item.json;
const sourceBinary = $('Convert Image to Binary').item.binary;
const response = $json;

// v9.5.7: the AI image quality check is now BEST-EFFORT, mirroring the video QA fix in v9.5.5.
// It used to `throw` whenever the QA call came back without parsable JSON - a rate limit (429),
// a refusal, an outage, or a plain text reply - and that threw away an image that had ALREADY
// been generated and paid for. The human approval gate and the two-stage audit are the real
// quality gates, so on any QA failure the image now passes through with the reason recorded.
function qaSkipped(reason) {
  return {
    json: {
      ...source,
      image_qa_passed: true,
      image_qa_confidence: 0,
      image_qa_reason: 'Automated QA skipped (' + String(reason).slice(0, 200) + '). Human review required.'
    },
    binary: sourceBinary
  };
}

const httpError = response?.error?.message || response?.body?.error?.message || response?.error;
if (httpError) return qaSkipped(typeof httpError === 'string' ? httpError : JSON.stringify(httpError));

try {
  let raw = response.choices?.[0]?.message?.content;
  if (!raw) return qaSkipped('QA returned no structured content');
  if (typeof raw === 'string') {
    raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    const objectMatch = raw.match(/\{[\s\S]*\}/);
    if (objectMatch) raw = objectMatch[0];
  }
  const result = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const threshold = Number($('Runtime Configuration').first().json.image_qa_threshold || 0.82);
  const passed = result.matches_topic === true
    && result.matches_required_visual_elements === true
    && result.matches_requested_scene === true
    && result.safe_and_realistic === true
    && result.has_forbidden_text_or_logo === false
    && Number(result.confidence || 0) >= threshold;
  return {
    json: {
      ...source,
      image_qa_passed: passed,
      image_qa_confidence: Number(result.confidence || 0),
      image_qa_reason: String(result.reason || '').trim()
    },
    binary: sourceBinary
  };
} catch (e) {
  return qaSkipped(e.message);
}

const source = $('Lock Image Row').item.json;
const retryMinutes = 2;
return {
  json: {
    id: source.id,
    image_status: 'Failed',
    image_attempts: Number(source.image_attempts || 1),
    status: 'Awaiting Approval',
    last_error: ('Image quality check rejected the result: ' + String($json.image_qa_reason || 'The image did not clearly match the requested service.')).slice(0, 1000),
    next_retry_at: new Date(Date.now() + retryMinutes * 60000).toISOString(),
    updated_at: new Date().toISOString(),
  },
};

const cfg = $('Runtime Configuration').first().json;
const enabled = cfg.telegram_preview_enabled === true || String(cfg.telegram_preview_enabled).toLowerCase() === 'true';
const chatId = String(cfg.telegram_chat_id || '').trim();
if (!enabled || !chatId || chatId === 'YOUR_TELEGRAM_CHAT_ID') return [];

const draft = $input.first().json;
const queue = $('Validate and Classify Queue Rows').item.json;
const brands = $('Read Brand Configuration').all().map(item => item.json || {});
const clean = value => String(value ?? '').trim();
const brand = brands.find(item => clean(item.brand_id) === clean(queue.brand_id)) || {};
const source = { ...brand, ...queue, ...draft };
const target = clean(source.target_platform).toLowerCase();
const platformNames = { facebook: 'FACEBOOK', instagram: 'INSTAGRAM', linkedin: 'LINKEDIN' };
const copy = target === 'facebook' ? clean(source.generated_facebook)
  : target === 'instagram' ? clean(source.generated_instagram)
  : clean(source.generated_linkedin);
if (!copy) return [];

const company = clean(source.company_name) || clean(source.brand_id) || 'Madama Group Brand';
const platform = platformNames[target] || target.toUpperCase() || 'SOCIAL';
const header = '📣 ' + platform + ' TEXT PREVIEW\n🏢 ' + company + '\n🧾 ' + clean(source.id) + '\n\n';
const footer = '\n\n🔎 REVIEW COPY — Telegram does not publish this content';
const maxBody = Math.max(0, 3900 - header.length - footer.length);
const body = copy.length > maxBody ? copy.slice(0, Math.max(0, maxBody - 3)).trim() + '...' : copy;
return [{ json: {
  telegram_chat_id: chatId,
  telegram_message: header + body + footer,
  telegram_platform: platform,
  content_id: clean(source.id),
} }];

