const source = $('Parse Video File Status').item.json;
const response = $json;

// v9.5.5: the AI quality check is now BEST-EFFORT. A rate limit (429), an outage, or a
// malformed reply used to throw the whole row away - discarding a video that had already
// generated successfully and been paid for. The human approval gate and the two-stage
// audit are the real quality gates, so on any QA failure the video passes through with
// the reason recorded instead of being destroyed.
function qaSkipped(reason) {
  return { json: {
    ...source,
    video_qa_passed: true,
    video_qa_confidence: 0,
    video_qa_reason: 'Automated QA skipped (' + String(reason).slice(0, 200) + '). Human review required.'
  } };
}

const httpError = response?.error?.message || response?.body?.error?.message || response?.error;
if (httpError) return qaSkipped(typeof httpError === 'string' ? httpError : JSON.stringify(httpError));

try {
  const contents = (response.steps || []).flatMap(step => Array.isArray(step.content) ? step.content : []);
  let raw = contents.filter(item => item?.type === 'text' && item.text).map(item => item.text).pop() || response.output_text || '';
  raw = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const objectMatch = raw.match(/\{[\s\S]*\}/);
  if (objectMatch) raw = objectMatch[0];
  if (!raw) return qaSkipped('QA returned no JSON result');
