  const passed = result.matches_topic === true
    && result.matches_active_task === true
    && result.coherent_motion === true
    && result.safe_and_realistic === true
    && result.professional_visual_quality === true
    && result.has_forbidden_text_or_logo === false
    && Number(result.confidence || 0) >= threshold;
  return { json: {
    ...source,
    video_qa_passed: passed,
    video_qa_confidence: Number(result.confidence || 0),
    video_qa_reason: String(result.reason || '').trim()
  } };
} catch (e) {
  return qaSkipped(e.message);
}

