const binaries = $binary || {};
const binaryKey = binaries.data ? 'data' : Object.keys(binaries)[0];
const incoming = binaryKey ? binaries[binaryKey] : null;
if (!incoming) throw new Error('The final Gemini video download did not return binary data.');
const safeId = String(source.id || 'video').replace(/[^a-zA-Z0-9_-]/g, '-');
const data = {
  ...incoming,
  fileName: safeId + '.mp4',
  fileExtension: 'mp4',
  mimeType: 'video/mp4'
};
return { json: { ...source, video_file_name: data.fileName }, binary: { data } };

