const fileId = String($('Upload Branded Video to Google Drive').item.json.id || '').trim();
if (!fileId) throw new Error('Branded Google Drive video upload did not return a file ID.');
return { json: {
  id: source.id,
  video_status: 'Ready',
  video_file_id: fileId,
  video_url: 'https://drive.usercontent.google.com/download?id=' + fileId + '&export=download',
  video_attempts: Number(source.video_attempts || 1),
  video_provider: source.video_provider || 'Google Gemini',
  video_duration_seconds: Number(source.video_duration_seconds || 8),
