  status: 'Awaiting Approval',
  last_error: '',
  next_retry_at: '',
  updated_at: new Date().toISOString()
} };

let source = {};
for (const name of ['Parse Branded Video Status','Parse Creatomate Video Render','Parse Video Validation','Parse Video File Status','Parse Video Generation','Build Video Generation Request','Prepare Video Lock']) {
  try { const candidate = $(name).first().json || {}; if (candidate.id) { source = candidate; break; } } catch {}
}
const raw = $json.error?.message || $json.body?.error?.message || $json.error_message || $json.message || $json.error || source._creatomate_video_error || source._video_file_error || 'Unknown video generation, branding, validation, download, or upload error';
const message = typeof raw === 'string' ? raw : JSON.stringify(raw);
const retryMinutes = Number($('Runtime Configuration').first().json.retry_minutes || 10);
return { json: { id: source.id, video_status: 'Failed', video_attempts: Number(source.video_attempts || 1), video_provider: source.video_provider || $('Runtime Configuration').first().json.video_provider || 'Google Gemini', video_duration_seconds: Number(source.video_duration_seconds || 8), video_aspect_ratio: source.video_aspect_ratio || '16:9', status: 'Awaiting Approval', last_error: ('Video workflow failed: ' + message).slice(0, 1000), next_retry_at: new Date(Date.now() + retryMinutes * 60000).toISOString(), updated_at: new Date().toISOString() } };

const source = $('Prepare Video Lock').item.json;
return { json: {
  id: source.id,
  video_status: 'Failed',
  video_attempts: Number(source.video_attempts || 1),
  video_provider: source.video_provider || 'Google Gemini',
