  status: 'Awaiting Approval',
  last_error: ('Video quality check rejected the result: ' + String($json.video_qa_reason || 'The video did not clearly match the requested service or quality bar.')).slice(0, 1000),
  next_retry_at: new Date(Date.now() + 2 * 60000).toISOString(),
  updated_at: new Date().toISOString()
} };

// v9.5.6 FIX: `return []` is invalid in per-item mode ("A 'json' property isn't an object").
// Switched to all-items mode so that, when Telegram previews are disabled or no chat id is
// configured, the node emits nothing instead of throwing. Binary data is carried per item.
const cfg = $('Runtime Configuration').first().json;
const enabled = cfg.telegram_preview_enabled === true || String(cfg.telegram_preview_enabled).toLowerCase() === 'true';
const chatId = String(cfg.telegram_chat_id || '').trim();
if (!enabled || !chatId || chatId === 'YOUR_TELEGRAM_CHAT_ID') return [];

const out = [];
for (const item of $input.all()) {
  const source = item.json || {};
  const target = String(source.target_platform || '').trim().toLowerCase();
  const copy = target === 'facebook' ? source.generated_facebook : target === 'instagram' ? source.generated_instagram : source.generated_linkedin;
  const caption = [
    '\ud83c\udfac ' + (target ? target.toUpperCase() : 'VIDEO') + ' \u2014 ' + String(source.company_name || source.brand_id || 'Madama Group'),
    '\ud83e\uddfe ' + String(source.id || ''),
    '\ud83c\udfa8 Branding: Creatomate \u2014 ' + String(source.video_provider || 'Video'),
    ...(Number(source.video_qa_confidence || 0) > 0
      ? ['\u2705 Gemini Video QA: ' + Math.round(Number(source.video_qa_confidence || 0) * 100) + '%']
      : ['\u2705 Branded source image + successful video render']),
    '',
    String(copy || '').trim()
  ].join('\n').slice(0, 1024);
  out.push({ json: { ...source, telegram_chat_id: chatId, telegram_caption: caption }, binary: item.binary });
}
return out;

return { json: {
  statusCode: 422,
  body: {
    message: 'The high-quality video was generated and saved, but LinkedIn video publishing requires the LinkedIn Videos API multipart asset-upload flow. This workflow intentionally did not publish a text-only replacement. Publish the Drive video manually or add an approved LinkedIn video-upload credential/adapter.'
  }
} };

