={{ (() => {
  const locked = $('Prepare Video Lock').first().json;
  const cfg = $('Runtime Configuration').first().json;
  if (!(cfg.creatomate_enabled === true || String(cfg.creatomate_enabled).toLowerCase() === 'true')) {
    throw new Error('Creatomate branding is required but creatomate_enabled is false.');
  }
  const pexelsPath = false;  // v9.5.0: stock-clip montage removed; branding is always an overlay
  let row = locked;
  if (pexelsPath) row = { ...locked, ...$json };

  const brands = $('Read Brand Configuration').all().map(item => item.json || {});
  const brand = brands.find(item => String(item.brand_id || '').trim() === String(row.brand_id || '').trim()) || {};
  const company = String(brand.company_name || row.company_name || row.brand_id || 'Company').trim();
  const subject = String(row.content_pillar || row.campaign || 'Professional Service').trim().slice(0, 70);
  const primary = String(brand.brand_primary_color || row.brand_primary_color || '#0F4C81').trim();
  const secondary = String(brand.brand_secondary_color || row.brand_secondary_color || '#001F3F').trim();
  const logo = String(brand.logo_url || row.logo_url || '').trim();
  const website = String(brand.website_url || row.link_url || '').replace(/^https?:\/\//i, '').replace(/\/$/, '').trim();
  const phone = String(brand.contact_phone || '').trim();
  const contact = [phone, website].filter(Boolean).join('  •  ').slice(0, 100);
  const vertical = String(row.video_aspect_ratio || '') === '9:16';
  const width = vertical ? 720 : 1280;
  const height = vertical ? 1280 : 720;
  const duration = pexelsPath
    ? Math.max(15, Math.min(30, Number(row.video_duration_seconds || 18)))
    : Math.max(3, Math.min(10, Number(row.video_duration_seconds || 8)));
  const textX = logo ? '21%' : '6%';
  const textWidth = logo ? '73%' : '88%';
  const elements = [];

  if (pexelsPath) {
    const clips = Array.isArray(row.pexels_clips) ? row.pexels_clips : [];
    if (clips.length < 3) throw new Error('Pexels montage requires at least three selected video clips.');
    const sceneDuration = duration / clips.length;
    clips.forEach((clip, index) => {
      elements.push({
        name: 'Pexels-Video-' + (index + 1),
        type: 'video',
        source: clip.source_url,
        fit: 'cover',
        width: '100%',
        height: '100%',
        duration: sceneDuration,
        trim_start: 0,
        trim_duration: sceneDuration,
        volume: '0%',
        track: 1,
        animations: [{ time: 0, duration: 0.35, type: 'fade' }]
      });
    });
    const captions = [
      subject,
      'Professional • Responsive • Reliable',
      'Supporting Facilities and Operations',
      'Qualified Service When You Need It',
      'Request Service Today'
    ];
    clips.forEach((clip, index) => {
      elements.push({
        name: 'Scene-Caption-' + (index + 1),
        type: 'text',
        text: captions[index] || subject,
        x: '6%',
        y: vertical ? '64%' : '65%',
        x_anchor: '0%',
        y_anchor: '0%',
        width: '88%',
        height: '10%',
        fill_color: '#FFFFFF',
        stroke_color: '#00000080',
        stroke_width: '0.8 vmin',
        font_family: 'Inter',
        font_weight: '800',
        font_size_minimum: vertical ? '3.2 vmin' : '2.5 vmin',
        font_size_maximum: vertical ? '6.0 vmin' : '4.8 vmin',
        text_wrap: true,
        time: index * sceneDuration,
        duration: sceneDuration,
        z_index: 20,
        animations: [{ time: 0, duration: 0.45, type: 'fade' }]
      });
    });
  } else {
    const rawFileId = String($('Upload Video to Google Drive').item.json.id || '').trim();
    if (!rawFileId) throw new Error('Raw Gemini video Drive file ID is missing.');
    const sourceUrl = 'https://drive.usercontent.google.com/download?id=' + rawFileId + '&export=download';
    elements.push({
      name: 'Source-Gemini-Video',
      type: 'video',
      source: sourceUrl,
      fit: 'cover',
      width: '100%',
      height: '100%',
      duration,
      trim_start: 0,
      trim_duration: duration,
      volume: '35%'
    });
  }

  elements.push(
    { name: 'Top-Accent', type: 'shape', x: '50%', y: '1.2%', width: '100%', height: '2.4%', fill_color: secondary, duration, z_index: 10 },
    { name: 'Brand-Band', type: 'shape', x: '50%', y: '89%', width: '100%', height: '22%', fill_color: primary, opacity: '96%', duration, z_index: 10 }
  );
  if (logo) elements.push({ name: 'Brand-Logo', type: 'image', source: logo, fit: 'contain', x: '3%', y: '80.5%', x_anchor: '0%', y_anchor: '0%', width: '15%', height: '14%', duration, z_index: 20, animations: [{ time: 0, duration: 0.6, type: 'fade' }] });
  elements.push(
    { name: 'Company-Name', type: 'text', text: company, x: textX, y: '80%', x_anchor: '0%', y_anchor: '0%', width: textWidth, height: '6%', fill_color: '#FFFFFF', font_family: 'Inter', font_weight: '800', font_size_minimum: '2.4 vmin', font_size_maximum: '4.4 vmin', text_wrap: false, duration, z_index: 20, animations: [{ time: 0, duration: 0.6, type: 'fade' }] },
    { name: 'Content-Subject', type: 'text', text: subject, x: textX, y: '87%', x_anchor: '0%', y_anchor: '0%', width: textWidth, height: '5%', fill_color: '#FFFFFF', font_family: 'Inter', font_weight: '600', font_size_minimum: '1.8 vmin', font_size_maximum: '3.2 vmin', text_wrap: false, duration, z_index: 20 },
    { name: 'Contact', type: 'text', text: contact, x: textX, y: '93%', x_anchor: '0%', y_anchor: '0%', width: textWidth, height: '4%', fill_color: '#FFFFFF', opacity: '90%', font_family: 'Inter', font_weight: '500', font_size_minimum: '1.4 vmin', font_size_maximum: '2.5 vmin', text_wrap: false, duration, z_index: 20 }
  );
  if (pexelsPath) elements.push({ name: 'Pexels-Credit', type: 'text', text: 'Footage: Pexels', x: '97%', y: '3.5%', x_anchor: '100%', y_anchor: '0%', width: '30%', height: '3%', fill_color: '#FFFFFF', opacity: '72%', font_family: 'Inter', font_weight: '500', font_size_minimum: '1.1 vmin', font_size_maximum: '1.7 vmin', text_align: 'right', duration, z_index: 20 });

  return JSON.stringify({
    output_format: 'mp4',
    width,
    height,
    duration,
    frame_rate: 30,
    elements,
    metadata: String(row.id || '')
  });
})() }}

